```python
def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_email(value):
        value = value.strip()
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if domain in ("gmail.com", "googlemail.com"):
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if (
            not local
            or not domain
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return local + "@" + domain

    def normalize_phone(value):
        marker = re.search(r"ext|x|#", value, flags=re.IGNORECASE)
        if marker:
            value = value[:marker.start()]

        digits = re.sub(r"\D", "", value)
        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in "01":
            return ""

        return digits

    def normalize_zip(value):
        value = value.strip()
        if "-" in value:
            value = value.split("-", 1)[0]

        if len(value) == 4 and value.isdigit():
            value = "0" + value

        return value if len(value) == 5 and value.isdigit() else ""

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def parse_updated(value):
        if "T" in value:
            return datetime.strptime(value, "%Y-%m-%dT%H:%M:%S")
        if "/" in value:
            return datetime.strptime(value, "%m/%d/%Y")
        return datetime.strptime(value, "%Y-%m-%d")

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    normalized_rows = []

    for index, row in enumerate(rows):
        normalized = {
            "index": index,
            "first_name": normalize_name(row["first_name"]),
            "last_name": normalize_name(row["last_name"]),
            "email": normalize_email(row["email"]),
            "phone": normalize_phone(row["phone"]),
            "zip": normalize_zip(row["zip"]),
            "source": row["source"].strip().lower(),
            "updated_dt": parse_updated(row["updated"]),
            "opted_out": is_opted_out(row["opted_out"]),
            "tags": {
                tag.strip().lower()
                for tag in re.split(r"[;,]", row["tags"])
                if tag.strip()
            },
        }

        # Rows without either usable contact identifier cannot participate.
        if normalized["email"] or normalized["phone"]:
            normalized_rows.append(normalized)

    count = len(normalized_rows)
    parent = list(range(count))

    def find(item):
        while parent[item] != item:
            parent[item] = parent[parent[item]]
            item = parent[item]
        return item

    def union(a, b):
        root_a = find(a)
        root_b = find(b)
        if root_a != root_b:
            parent[root_b] = root_a

    email_owner = {}
    phone_name_owner = {}

    for i, row in enumerate(normalized_rows):
        email = row["email"]
        if email:
            if email in email_owner:
                union(i, email_owner[email])
            else:
                email_owner[email] = i

        if row["phone"] and row["last_name"]:
            phone_name_key = (
                row["phone"],
                row["last_name"].casefold(),
            )
            if phone_name_key in phone_name_owner:
                union(i, phone_name_owner[phone_name_key])
            else:
                phone_name_owner[phone_name_key] = i

    groups = {}
    for i, row in enumerate(normalized_rows):
        groups.setdefault(find(i), []).append(row)

    def choose(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""

        best = max(
            candidates,
            key=lambda row: (
                row["source"].casefold() == "manual",
                row["updated_dt"],
                -row["index"],
            ),
        )
        return best[field]

    output = []

    for group in groups.values():
        tags = set()
        for row in group:
            tags.update(row["tags"])

        latest_updated = max(row["updated_dt"] for row in group)

        output.append({
            "first_name": choose(group, "first_name"),
            "last_name": choose(group, "last_name"),
            "zip": choose(group, "zip"),
            "email": choose(group, "email"),
            "phone": choose(group, "phone"),
            "source": choose(group, "source"),
            "tags": ";".join(sorted(tags)),
            "opted_out": (
                "Y" if any(row["opted_out"] for row in group) else "N"
            ),
            "updated": latest_updated.strftime("%Y-%m-%d"),
            "_earliest_index": min(row["index"] for row in group),
        })

    output.sort(key=lambda person: person["_earliest_index"])
    for person in output:
        del person["_earliest_index"]

    return output
